create extension if not exists pgcrypto;
create table if not exists public.admin_users (user_id uuid primary key references auth.users(id) on delete cascade, created_at timestamptz default now());
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.admin_users where user_id=auth.uid()) $$;
create table if not exists public.appraisal_requests (id uuid primary key default gen_random_uuid(),name text not null,email text not null,phone text not null,property_address text not null,property_type text not null,purpose text not null,preferred_inspection_date date,message text,fee numeric(12,2),status text not null default 'new',created_at timestamptz default now());
create table if not exists public.jobs (id uuid primary key default gen_random_uuid(),title text not null,location text default 'United States',department text,employment_type text default 'Full-time',salary_range text,description text not null,requirements text,closing_date date,published boolean not null default false,created_at timestamptz default now());
create table if not exists public.job_applications (id uuid primary key default gen_random_uuid(),job_id uuid not null references public.jobs(id) on delete cascade,name text not null,email text not null,phone text,linkedin_url text,resume_url text,cover_letter text,status text not null default 'new',created_at timestamptz default now());
alter table public.admin_users enable row level security;alter table public.appraisal_requests enable row level security;alter table public.jobs enable row level security;alter table public.job_applications enable row level security;
drop policy if exists "public can submit appraisals" on public.appraisal_requests;create policy "public can submit appraisals" on public.appraisal_requests for insert to anon,authenticated with check(true);
drop policy if exists "admins manage appraisals" on public.appraisal_requests;create policy "admins manage appraisals" on public.appraisal_requests for all to authenticated using(public.is_admin()) with check(public.is_admin());
drop policy if exists "public reads published jobs" on public.jobs;create policy "public reads published jobs" on public.jobs for select to anon,authenticated using(published=true or public.is_admin());
drop policy if exists "admins manage jobs" on public.jobs;create policy "admins manage jobs" on public.jobs for all to authenticated using(public.is_admin()) with check(public.is_admin());
drop policy if exists "public submits applications" on public.job_applications;create policy "public submits applications" on public.job_applications for insert to anon,authenticated with check(true);
drop policy if exists "admins manage applications" on public.job_applications;create policy "admins manage applications" on public.job_applications for all to authenticated using(public.is_admin()) with check(public.is_admin());
drop policy if exists "admins read admin_users" on public.admin_users;create policy "admins read admin_users" on public.admin_users for select to authenticated using(public.is_admin());
